import json, subprocess, sys
from pathlib import Path

repo = \"kimhw8084/expo-base\"
commit = \"3eb76c5ea0bee26881326fc8f87c12f0cbc8ce73\"
notes = Path(\"docs/RELEASE_NOTES_1.1.0.md\").read_text()
old_open = \"is a minor-compatible source release candidate building\"
new_open = \"is the released GitHub/source framework version and minor-compatible source release building\"
old_close = \"This candidate does not publish npm packages, create a GitHub Release or tag, deploy EAS/store artifacts, merge or move \" + chr(96) + \"main\" + chr(96) + \", or release a downstream product.\"
new_close = \"This GitHub/source release does not publish npm packages, deploy Expo/EAS/store artifacts, or establish downstream-product production readiness.\"
if notes.count(old_open) "'!= 1 or notes.count(old_close) != 1:
    print(json.dumps({"result": "ABORT", "reason": "release notes did not match expected source text"}, sort_keys=True)); sys.exit(10)
body = notes.replace(old_open, new_open).replace(old_close, new_close)
if body.replace(new_open, old_open).replace(new_close, old_close) != notes:
    print(json.dumps({"result": "ABORT", "reason": "in-memory body changed content beyond approved wording"}, sort_keys=True)); sys.exit(11)
required = [
    "the released GitHub/source framework version", "## What changed since 1.0.0",
    "Standalone generated applications", "React Hook Form integration",
    "Application-facing compatibility", "Safer migration planning",
    "Correctness and acceptance hardening", "## Compatibility and migration",
    "SemVer minor release", "## Boundaries unchanged",
    "Android native acceptance remains deferred and uncertified",
    "No Android PASS, TalkBack usability acceptance, or universal-native support is claimed.",
    "Human VoiceOver usability, exact real-device Dynamic Type behavior, and physical-device hardware behavior remain outside the evidence boundary.",
    "Generated product integrations remain product-owned.", new_close,
]
def body_checks(text):
    return {
        "opening_released": "the released GitHub/source framework version" in text and "release candidate" not in text,
        "capability_summary": all(s in text for s in required[1:7]),
        "compatibility_text": all(s in text for s in required[7:9]),
        "android_deferred_uncertified_no_pass": all(s in text for s in required[9:11]),
        "voiceover_dynamic_type_hardware_nonclaims": required[11] in text,
        "generated_integrations_product_owned": required[12] in text,
        "durable_release_boundary": new_close in text and "This candidate does not" not in text,
    }
if not all(body_checks(body).values()):
    print(json.dumps({"result": "ABORT", "reason": "release body boundary validation failed", "body_checks": body_checks(body)}, sort_keys=True)); sys.exit(12)

def run(args, **kwargs):
    return subprocess.run(args, text=True, capture_output=True, **kwargs)
def valid_release(data):
    return (data.get("tag_name") == "v1.1.0" and data.get("name") == "Expo Base v1.1.0"
            and data.get("draft") is False and data.get("prerelease") is False
            and bool(data.get("published_at")) and bool(data.get("tarball_url"))
            and bool(data.get("zipball_url")) and all(body_checks(data.get("body") or "").values()))

refs = run(["git", "ls-remote", "origin", "refs/heads/main", "refs/tags/v1.1.0", "refs/tags/v1.1.0''^{}"]).stdout.splitlines()
remote = {line.split()[1]: line.split()[0] for line in refs}
tag_obj = run(["git", "rev-parse", "refs/tags/v1.1.0"]).stdout.strip()
tag_type = run(["git", "cat-file", "-t", "refs/tags/v1.1.0"]).stdout.strip()
tag_target = run(["git", "rev-parse", "refs/tags/v1.1.0''^{commit}"]).stdout.strip()
if remote.get("refs/heads/main") != commit or remote.get("refs/tags/v1.1.0") != tag_obj or remote.get("refs/tags/v1.1.0''^{}") != commit or tag_type != "tag" or tag_target != commit:
    print(json.dumps({"result": "ABORT", "reason": "remote main or annotated tag identity changed"}, sort_keys=True)); sys.exit(13)

def get_release():
