if state == "present":
    result = "ALREADY_RELEASED" if valid_release(data) else "MISMATCH_FAIL_CLOSED"
    print(json.dumps({"result": result, "release_id": data.get("id"), "tag_name": data.get("tag_name"), "name": data.get("name"), "draft": data.get("draft"), "prerelease": data.get("prerelease"), "published_at": data.get("published_at"), "body_checks": body_checks(data.get("body") or ""), "tag_object_sha": tag_obj, "peeled_commit": tag_target}, sort_keys=True))
    sys.exit(0 if result == "ALREADY_RELEASED" else 16)

payload = {"tag_name": "v1.1.0", "name": "Expo Base v1.1.0", "body": body, "draft": False, "prerelease": False}
post = run(["gh", "api", "--method", "POST", f"repos/{repo}/releases", "--input", "-"], input=json.dumps(payload))
